import asyncio
import concurrent.futures
import contextlib
import sys
import logging
import uvicorn
from . import reloader


class ProactorLoopConfig(uvicorn.config.Config):
    def setup_event_loop(self):
        if sys.platform == 'win32':
            # set ProactorEventLoop() to let asyncio.create_subprocess_shell() work on Windows
            loop = asyncio.ProactorEventLoop()
            asyncio.set_event_loop(loop)
        else:
            super().setup_event_loop()


def is_https_wanted(**kwargs):
    return ('ssl_certfile' in kwargs) and (kwargs['ssl_certfile'])


def run(app, allow_restarts, **kwargs):
    """
    Our variant of uvicorn.run() allowing for "whole python reload" functionality.

    Moreover, we do not support reload nor workers of uvicorn.run().
    """
    https_wanted = is_https_wanted(**kwargs)
    http_port = 80 if kwargs['port'] == 443 else kwargs['port']
    https_port = 443 if kwargs['port'] == 443 else kwargs['port'] + 1
    if https_wanted:
        kwargs['port'] = https_port

    config = ProactorLoopConfig(app, **kwargs)
    server = uvicorn.Server(config=config)

    if (config.reload or config.workers > 1) and not isinstance(app, str):
        logger = logging.getLogger("uvicorn.error")
        logger.critical("ue_proxy doesn't support '--reload' nor '--workers' of uvicorn.")
        exit(1)

    def trigger_shutdown():
        server.should_exit = True  # the only way to programmatically stop uvicorn

    reloader.register(shutdown=trigger_shutdown)
    if https_wanted:
        with run_redirector_in_backgroud(host=kwargs['host'], http_port=http_port, https_port=https_port):
            server.run()
    else:  # raw http
        server.run()
    if allow_restarts and reloader.should_restart():
        reloader.restart()


@contextlib.contextmanager
def run_redirector_in_backgroud(host, http_port, https_port):
    with concurrent.futures.ProcessPoolExecutor() as executor:
        redirection = f"http://{host}:{http_port} --> https://{host}:{https_port}"
        print(f"Starting HTTP redirection server - redirecting {redirection}")  # noqa: T201
        executor.submit(uvicorn.run,
                        "taf.ue.proxy.mngr._vendor.proxy_resources.redirector:redirector",
                        host=host, port=http_port)
        yield
